'use strict';

/**
 * The training loop's trees (docs/LEARNED-RULEBOOK.md R30: each trial runs in its own copy, its adapters
 * generated by `node scripts/sync-harness.js`, so trials never touch the live tree), and the promotion
 * branch (R25: a kept change becomes a pull request the owner reviews; this writes the branch, never
 * pushes it and never opens the pull request).
 *
 *   exportTree(root, dir, { git })        the repository's HEAD as plain files in dir (git archive); refuses a
 *                                         repository with uncommitted changes, so the baseline is HEAD exactly
 *   copyTree(root, dir)                   the working tree's files in dir (no .git, node_modules): tests' copier
 *   prepareTree(dir, { proposal, run })   the proposal applied (if any), adapters synced, strategies validated
 *   changedFiles(baseDir, candDir)        [rel] that differ (content, or a link's target), added or removed
 *   writeBranch(root, { branch, base, fromDir, files, message, git })   a local branch: base plus those files
 *                                         from fromDir, committed without a checkout; refuses an existing branch
 *   removeTree(dir, owned)                deletes dir only when it is one of the loop's own (owned: its parent)
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { applyProposal } = require('./proposal');

const SKIP = new Set(['.git', 'node_modules']);
// What node scripts/sync-harness.js writes (CLAUDE.md, "Generated, never edit by hand").
const GENERATED = /^(workspace|\.codex|qwen-extension|\.agents|\.claude-plugin|\.codex-plugin)\//;

function gitRunner(root) {
  return (args, opts = {}) => {
    const r = spawnSync('git', args, { cwd: root, encoding: opts.encoding === null ? null : 'utf8', input: opts.input, env: { ...process.env, ...(opts.env || {}) }, maxBuffer: 1 << 28 });
    if (r.status !== 0) throw new Error(`git ${args[0]}: ${String(r.stderr || '').trim() || `exit ${r.status}`}`);
    return r.stdout;
  };
}

function exportTree(root, dir, { git = gitRunner(root) } = {}) {
  const dirty = String(git(['status', '--porcelain', '--untracked-files=no'])).trim();
  if (dirty) throw new Error(`the repository has uncommitted changes; the champion is HEAD exactly, so commit or set them aside first:\n${dirty.split('\n').slice(0, 10).join('\n')}`);
  const commit = String(git(['rev-parse', 'HEAD'])).trim();
  fs.mkdirSync(dir, { recursive: true });
  const tar = git(['archive', '--format=tar', commit], { encoding: null });
  const r = spawnSync('tar', ['-x', '-C', dir], { input: tar });
  if (r.status !== 0) throw new Error(`tar: ${String(r.stderr || '').trim()}`);
  return commit;
}

function copyTree(from, dir) {
  const root = path.resolve(from);
  fs.cpSync(root, dir, { recursive: true, verbatimSymlinks: true, filter: src => !SKIP.has(path.basename(src)) || path.dirname(src) !== root });
  return null;
}

function runNode(dir, args) {
  const r = spawnSync(process.execPath, args, { cwd: dir, encoding: 'utf8', env: { ...process.env, FTH_STRATEGIES_DIRS: '', FTH_ACCOUNTS_DIRS: '' } });
  if (r.status !== 0) throw new Error(`${args.join(' ')}: ${String(r.stderr || r.stdout || '').trim().split('\n').slice(-5).join(' | ')}`);
  return r.stdout;
}

/** Applies the proposal (if any), then regenerates the adapters and validates the strategies, in the tree. */
function prepareTree(dir, { proposal = null, run = runNode } = {}) {
  const files = proposal ? applyProposal(proposal, dir) : [];
  run(dir, [path.join(dir, 'scripts', 'sync-harness.js')]);
  run(dir, [path.join(dir, 'scripts', 'strategies.js'), 'validate']);
  return files;
}

function walk(dir, rel = '') {
  const out = [];
  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    if (!rel && SKIP.has(e.name)) continue;
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) out.push(...walk(dir, r));
    else out.push(r);
  }
  return out;
}

function contentOf(file) {
  const st = fs.lstatSync(file, { throwIfNoEntry: false });
  if (!st) return null;
  return st.isSymbolicLink() ? `link:${fs.readlinkSync(file)}` : fs.readFileSync(file);
}

function changedFiles(baseDir, candDir) {
  const all = [...new Set([...walk(baseDir), ...walk(candDir)])].sort();
  return all.filter(rel => {
    const a = contentOf(path.join(baseDir, rel));
    const b = contentOf(path.join(candDir, rel));
    if (a === null || b === null) return a !== b;
    return Buffer.isBuffer(a) && Buffer.isBuffer(b) ? !a.equals(b) : a !== b;
  });
}

const BRANCH = /^[A-Za-z0-9][A-Za-z0-9._/-]{0,99}$/;

function writeBranch(root, { branch, base, fromDir, files, message, git = gitRunner(root), indexFile }) {
  if (!BRANCH.test(branch) || branch.includes('..') || branch.endsWith('.lock') || branch.endsWith('/')) throw new Error(`branch name: ${branch}`);
  let exists = true;
  try { git(['rev-parse', '--verify', '--quiet', `refs/heads/${branch}`]); } catch (_err) { exists = false; }
  if (exists) throw new Error(`branch ${branch} already exists: the loop never overwrites a branch`);
  const env = { GIT_INDEX_FILE: indexFile };
  git(['read-tree', base], { env });
  for (const rel of files) {
    const abs = path.join(fromDir, rel);
    const st = fs.lstatSync(abs, { throwIfNoEntry: false });
    if (!st) { git(['update-index', '--force-remove', '--', rel], { env }); continue; }
    const link = st.isSymbolicLink();
    const sha = String(link ? git(['hash-object', '-w', '--stdin'], { input: fs.readlinkSync(abs) }) : git(['hash-object', '-w', '--', abs])).trim();
    const mode = link ? '120000' : (st.mode & 0o111 ? '100755' : '100644');
    git(['update-index', '--add', '--cacheinfo', `${mode},${sha},${rel}`], { env });
  }
  const tree = String(git(['write-tree'], { env })).trim();
  const commit = String(git(['commit-tree', tree, '-p', base, '-F', '-'], { input: message })).trim();
  git(['update-ref', `refs/heads/${branch}`, commit, '']);
  try { fs.unlinkSync(indexFile); } catch (_err) { /* already gone */ }
  return commit;
}

/** Deletes a tree the loop made: only an exact child of `owned`, never anything else. */
function removeTree(dir, owned) {
  const rel = path.relative(path.resolve(owned), path.resolve(dir));
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) throw new Error(`${dir} is not one of the loop's own trees (under ${owned})`);
  fs.rmSync(dir, { recursive: true, force: true });
}

module.exports = { GENERATED, exportTree, copyTree, prepareTree, changedFiles, writeBranch, removeTree, gitRunner };
